68	impl SceneEffectRequest {
69	    fn from_command(name: &str, args: &[(Option<String>, TransitionArg)]) -> Self {
70	        let name_lower = name.to_lowercase();
71	        let duration = Self::extract_duration(args);
72	
73	        if name_lower.contains("blur") {
74	            if name_lower.contains("out") {
75	                SceneEffectRequest {
76	                    kind: SceneEffectKind::BlurOut,
77	                    duration: duration.unwrap_or(0.5),
78	                }
79	            } else {
80	                SceneEffectRequest {
81	                    kind: SceneEffectKind::Blur,
82	                    duration: duration.unwrap_or(0.5),
83	                }
84	            }
85	        } else if name_lower.contains("dim") {
86	            if name_lower.contains("reset") {
87	                SceneEffectRequest {
88	                    kind: SceneEffectKind::DimReset,
89	                    duration: 0.0,
90	                }
91	            } else {
92	                let level = Self::extract_level(args);
93	                let dim = (level / 7.0).clamp(0.0, 1.0);
94	                SceneEffectRequest {
95	                    kind: SceneEffectKind::Dim { level: dim },
96	                    duration: 0.0,
97	                }
98	            }
99	        } else {
100	            let (ax, ay) = if name_lower.contains("vertical") {
101	                (0.0, 8.0)
102	            } else if name_lower.contains("bounce") {
103	                (0.0, 5.0)
104	            } else {
105	                (6.0, 4.0)
106	            };
107	            SceneEffectRequest {
108	                kind: SceneEffectKind::Shake {
109	                    amplitude_x: ax,
110	                    amplitude_y: ay,
111	                },
112	                duration: duration.unwrap_or(0.3),
113	            }
114	        }
115	    }
116	
117	    fn extract_duration(args: &[(Option<String>, TransitionArg)]) -> Option<f32> {
118	        for (key, val) in args {
119	            let is_duration = key.as_deref() == Some("duration")
120	                || (key.is_none() && matches!(val, TransitionArg::Number(_)));
121	            if is_duration && let TransitionArg::Number(n) = val {
122	                return Some(*n as f32);
123	            }
124	        }
125	        None
126	    }
127	
128	    fn extract_level(args: &[(Option<String>, TransitionArg)]) -> f32 {
129	        for (key, val) in args {
130	            if key.as_deref() == Some("level")
131	                && let TransitionArg::Number(n) = val
132	            {
133	                return *n as f32;
134	            }
135	        }
136	        1.0
137	    }
138	}
