146	enum TransitionKind {
147	    None,
148	    Dissolve,
149	    Fade,
150	    FadeWhite,
151	    Move,
152	    Rule {
153	        mask_path: String,
154	        reversed: bool,
155	        ramp: f32,
156	    },
157	}
158	
159	fn resolve_transition(transition: &Transition) -> (TransitionKind, f32) {
160	    let name = transition.name.to_lowercase();
161	    let duration = transition.get_duration().map(|d| d as f32);
162	    match name.as_str() {
163	        "fade" => (TransitionKind::Fade, duration.unwrap_or(0.5)),
164	        "fadewhite" => (TransitionKind::FadeWhite, duration.unwrap_or(0.5)),
165	        "move" | "slide" => (TransitionKind::Move, duration.unwrap_or(0.3)),
166	        "none" => (TransitionKind::None, 0.0),
167	        "rule" => {
168	            let mask_path = transition
169	                .get_arg("mask", 1)
170	                .and_then(|a| match a {
171	                    TransitionArg::String(s) => Some(s.clone()),
172	                    _ => None,
173	                })
174	                .unwrap_or_default();
175	            let reversed = transition.get_reversed().unwrap_or(false);
176	            let ramp = transition
177	                .get_arg("ramp", 3)
178	                .and_then(|a| match a {
179	                    TransitionArg::Number(n) => Some(*n as f32),
180	                    _ => None,
181	                })
182	                .unwrap_or(0.1);
183	            (
184	                TransitionKind::Rule {
185	                    mask_path,
186	                    reversed,
187	                    ramp,
188	                },
189	                duration.unwrap_or(0.5),
190	            )
191	        }
192	        _ => (TransitionKind::Dissolve, duration.unwrap_or(0.3)),
193	    }
194	}
