207	impl Default for CommandExecutor {
208	    fn default() -> Self {
209	        Self::new()
210	    }
211	}
212	
213	impl CommandExecutor {
214	    pub fn new() -> Self {
215	        Self {
216	            last_output: CommandOutput::default(),
217	        }
218	    }
219	
220	    pub fn execute(
221	        &mut self,
222	        cmd: &Command,
223	        rs: &mut RenderState,
224	        manifest: &Manifest,
225	    ) -> ExecuteResult {
226	        self.last_output = CommandOutput::default();
227	        match cmd {
228	            Command::ShowBackground { .. } | Command::ChangeScene { .. } => {
229	                self.execute_background(cmd, rs)
230	            }
231	            Command::ShowCharacter { .. }
232	            | Command::HideCharacter { .. }
233	            | Command::ClearCharacters => self.execute_character(cmd, rs, manifest),
234	            Command::ShowText { .. }
235	            | Command::ExtendText { .. }
236	            | Command::TextBoxHide
237	            | Command::TextBoxShow
238	            | Command::TextBoxClear
239	            | Command::SetTextMode(_) => self.execute_text(cmd, rs),
240	            Command::PresentChoices { .. } => self.execute_choices(cmd, rs),
241	            Command::PlayBgm { .. }
242	            | Command::StopBgm { .. }
243	            | Command::BgmDuck
244	            | Command::BgmUnduck
245	            | Command::PlaySfx { .. } => self.execute_audio(cmd),
246	            Command::ChapterMark { .. } | Command::TitleCard { .. } => {
247	                self.execute_effects(cmd, rs)
248	            }
249	            Command::SceneEffect { .. } => self.execute_scene_effect(cmd),
250	            Command::Cutscene { .. } | Command::FullRestart | Command::RequestUI { .. } => {
251	                self.execute_control(cmd)
252	            }
253	        }
254	    }
255	
256	    // ── 背景 / 场景切换 ──────────────────────────────────────────────────────
257	
258	    fn execute_background(&self, cmd: &Command, rs: &mut RenderState) -> ExecuteResult {
259	        match cmd {
260	            Command::ShowBackground {
261	                path, transition, ..
262	            } => {
263	                if let Some(t) = transition {
264	                    let (kind, duration) = resolve_transition(t);
265	                    if let TransitionKind::None = kind {
266	                        rs.set_background(path.clone());
267	                    } else {
268	                        rs.background_transition = Some(BackgroundTransition {
269	                            old_background: rs.current_background.clone(),
270	                            new_background: path.clone(),
271	                            duration,
272	                        });
273	                        rs.set_background(path.clone());
274	                    }
275	                } else {
276	                    rs.set_background(path.clone());
277	                }
278	                ExecuteResult::Ok
279	            }
280	            Command::ChangeScene {
281	                path, transition, ..
282	            } => {
283	                if let Some(t) = transition {
284	                    let (kind, duration) = resolve_transition(t);
285	                    match kind {
286	                        TransitionKind::Dissolve | TransitionKind::Move => {
287	                            rs.background_transition = Some(BackgroundTransition {
288	                                old_background: rs.current_background.clone(),
289	                                new_background: path.clone(),
290	                                duration,
291	                            });
292	                            rs.set_background(path.clone());
293	                        }
294	                        TransitionKind::Fade => {
295	                            rs.scene_transition = Some(SceneTransition {
296	                                transition_type: SceneTransitionKind::Fade,
297	                                phase: SceneTransitionPhaseState::FadeIn,
298	                                duration,
299	                                pending_background: Some(path.clone()),
300	                            });
301	                        }
302	                        TransitionKind::FadeWhite => {
303	                            rs.scene_transition = Some(SceneTransition {
304	                                transition_type: SceneTransitionKind::FadeWhite,
305	                                phase: SceneTransitionPhaseState::FadeIn,
306	                                duration,
307	                                pending_background: Some(path.clone()),
308	                            });
309	                        }
310	                        TransitionKind::Rule {
311	                            mask_path,
312	                            reversed,
313	                            ramp,
314	                        } => {
315	                            rs.scene_transition = Some(SceneTransition {
316	                                transition_type: SceneTransitionKind::Rule {
317	                                    mask_path,
318	                                    reversed,
319	                                    ramp,
320	                                },
321	                                phase: SceneTransitionPhaseState::FadeIn,
322	                                duration,
323	                                pending_background: Some(path.clone()),
324	                            });
325	                        }
326	                        TransitionKind::None => rs.set_background(path.clone()),
327	                    }
328	                } else {
329	                    rs.set_background(path.clone());
330	                }
