564	    pub fn execute_batch(
565	        &mut self,
566	        cmds: &[Command],
567	        rs: &mut RenderState,
568	        manifest: &Manifest,
569	    ) -> BatchOutput {
570	        let mut final_result = ExecuteResult::Ok;
571	        let mut audio_commands = Vec::new();
572	        let mut scene_effect_request = None;
573	        for cmd in cmds {
574	            let result = self.execute(cmd, rs, manifest);
575	            if let Some(audio) = self.last_output.audio_command.take() {
576	                audio_commands.push(audio);
577	            }
578	            if let Some(effect) = self.last_output.scene_effect_request.take() {
579	                scene_effect_request = Some(effect);
580	            }
581	            if result != ExecuteResult::Ok {
582	                final_result = result;
583	            }
584	        }
585	        BatchOutput {
586	            result: final_result,
587	            audio_commands,
588	            scene_effect_request,
