use std::collections::HashMap;

use serde::Serialize;
use vn_runtime::{
    command::{Command, TextMode, Transition, TransitionArg},
    state::VarValue,
};

use crate::{
    manifest::Manifest,
    render_state::{
        BackgroundTransition, ChoiceItem, RenderState, SceneTransition, SceneTransitionKind,
        SceneTransitionPhaseState,
    },
};

#[derive(Debug, Clone, PartialEq, Default, Serialize)]
pub enum ExecuteResult {
    #[default]
    Ok,
    WaitForClick,
    WaitForChoice {
        choice_count: usize,
    },
    WaitForCutscene {
        video_path: String,
    },
    FullRestart,
    RequestUI {
        key: String,
        mode: String,
        params: HashMap<String, VarValue>,
    },
}

#[derive(Debug, Clone, Serialize)]
pub enum AudioCommand {
    PlayBgm {
        path: String,
        looping: bool,
        fade_in: Option<f32>,
    },
    StopBgm {
        fade_out: Option<f32>,
    },
    BgmDuck,
    BgmUnduck,
    PlaySfx {
        path: String,
    },
}

#[derive(Debug, Clone)]
pub struct SceneEffectRequest {
    pub kind: SceneEffectKind,
    pub duration: f32,
}

#[derive(Debug, Clone)]
pub enum SceneEffectKind {
    Shake { amplitude_x: f32, amplitude_y: f32 },
    Blur,
    BlurOut,
    Dim { level: f32 },
    DimReset,
}

impl SceneEffectRequest {
    fn from_command(name: &str, args: &[(Option<String>, TransitionArg)]) -> Self {
        let name_lower = name.to_lowercase();
        let duration = Self::extract_duration(args);

        if name_lower.contains("blur") {
            if name_lower.contains("out") {
                SceneEffectRequest {
                    kind: SceneEffectKind::BlurOut,
                    duration: duration.unwrap_or(0.5),
                }
            } else {
                SceneEffectRequest {
                    kind: SceneEffectKind::Blur,
                    duration: duration.unwrap_or(0.5),
                }
            }
        } else if name_lower.contains("dim") {
            if name_lower.contains("reset") {
                SceneEffectRequest {
                    kind: SceneEffectKind::DimReset,
                    duration: 0.0,
                }
            } else {
                let level = Self::extract_level(args);
                let dim = (level / 7.0).clamp(0.0, 1.0);
                SceneEffectRequest {
                    kind: SceneEffectKind::Dim { level: dim },
                    duration: 0.0,
                }
            }
        } else {
            let (ax, ay) = if name_lower.contains("vertical") {
                (0.0, 8.0)
            } else if name_lower.contains("bounce") {
                (0.0, 5.0)
            } else {
                (6.0, 4.0)
            };
            SceneEffectRequest {
                kind: SceneEffectKind::Shake {
                    amplitude_x: ax,
                    amplitude_y: ay,
                },
                duration: duration.unwrap_or(0.3),
            }
        }
    }

    fn extract_duration(args: &[(Option<String>, TransitionArg)]) -> Option<f32> {
        for (key, val) in args {
            let is_duration = key.as_deref() == Some("duration")
                || (key.is_none() && matches!(val, TransitionArg::Number(_)));
            if is_duration && let TransitionArg::Number(n) = val {
                return Some(*n as f32);
            }
        }
        None
    }

    fn extract_level(args: &[(Option<String>, TransitionArg)]) -> f32 {
        for (key, val) in args {
            if key.as_deref() == Some("level")
                && let TransitionArg::Number(n) = val
            {
                return *n as f32;
            }
        }
        1.0
    }
}

#[derive(Debug, Clone, Default)]
pub struct CommandOutput {
    pub audio_command: Option<AudioCommand>,
    pub scene_effect_request: Option<SceneEffectRequest>,
}

enum TransitionKind {
    None,
    Dissolve,
    Fade,
    FadeWhite,
    Move,
    Rule {
        mask_path: String,
        reversed: bool,
        ramp: f32,
    },
}

fn resolve_transition(transition: &Transition) -> (TransitionKind, f32) {
    let name = transition.name.to_lowercase();
    let duration = transition.get_duration().map(|d| d as f32);
    match name.as_str() {
        "fade" => (TransitionKind::Fade, duration.unwrap_or(0.5)),
        "fadewhite" => (TransitionKind::FadeWhite, duration.unwrap_or(0.5)),
        "move" | "slide" => (TransitionKind::Move, duration.unwrap_or(0.3)),
        "none" => (TransitionKind::None, 0.0),
        "rule" => {
            let mask_path = transition
                .get_arg("mask", 1)
                .and_then(|a| match a {
                    TransitionArg::String(s) => Some(s.clone()),
                    _ => None,
                })
                .unwrap_or_default();
            let reversed = transition.get_reversed().unwrap_or(false);
            let ramp = transition
                .get_arg("ramp", 3)
                .and_then(|a| match a {
                    TransitionArg::Number(n) => Some(*n as f32),
                    _ => None,
                })
                .unwrap_or(0.1);
            (
                TransitionKind::Rule {
                    mask_path,
                    reversed,
                    ramp,
                },
                duration.unwrap_or(0.5),
            )
        }
        _ => (TransitionKind::Dissolve, duration.unwrap_or(0.3)),
    }
}

pub struct BatchOutput {
    pub result: ExecuteResult,
    pub audio_commands: Vec<AudioCommand>,
    pub scene_effect_request: Option<SceneEffectRequest>,
}

#[derive(Debug)]
pub struct CommandExecutor {
    pub last_output: CommandOutput,
}

impl Default for CommandExecutor {
    fn default() -> Self {
        Self::new()
    }
}

impl CommandExecutor {
    pub fn new() -> Self {
        Self {
            last_output: CommandOutput::default(),
        }
    }

    pub fn execute(
        &mut self,
        cmd: &Command,
        rs: &mut RenderState,
        manifest: &Manifest,
    ) -> ExecuteResult {
        self.last_output = CommandOutput::default();
        match cmd {
            Command::ShowBackground { .. } | Command::ChangeScene { .. } => {
                self.execute_background(cmd, rs)
            }
            Command::ShowCharacter { .. }
            | Command::HideCharacter { .. }
            | Command::ClearCharacters => self.execute_character(cmd, rs, manifest),
            Command::ShowText { .. }
            | Command::ExtendText { .. }
            | Command::TextBoxHide
            | Command::TextBoxShow
            | Command::TextBoxClear
            | Command::SetTextMode(_) => self.execute_text(cmd, rs),
            Command::PresentChoices { .. } => self.execute_choices(cmd, rs),
            Command::PlayBgm { .. }
            | Command::StopBgm { .. }
            | Command::BgmDuck
            | Command::BgmUnduck
            | Command::PlaySfx { .. } => self.execute_audio(cmd),
            Command::ChapterMark { .. } | Command::TitleCard { .. } => {
                self.execute_effects(cmd, rs)
            }
            Command::SceneEffect { .. } => self.execute_scene_effect(cmd),
            Command::Cutscene { .. } | Command::FullRestart | Command::RequestUI { .. } => {
                self.execute_control(cmd)
            }
        }
    }

    // ── 背景 / 场景切换 ──────────────────────────────────────────────────────

    fn execute_background(&self, cmd: &Command, rs: &mut RenderState) -> ExecuteResult {
        match cmd {
            Command::ShowBackground {
                path, transition, ..
            } => {
                if let Some(t) = transition {
                    let (kind, duration) = resolve_transition(t);
                    if let TransitionKind::None = kind {
                        rs.set_background(path.clone());
                    } else {
                        rs.background_transition = Some(BackgroundTransition {
                            old_background: rs.current_background.clone(),
                            new_background: path.clone(),
                            duration,
                        });
                        rs.set_background(path.clone());
                    }
                } else {
                    rs.set_background(path.clone());
                }
                ExecuteResult::Ok
            }
            Command::ChangeScene {
                path, transition, ..
            } => {
                if let Some(t) = transition {
                    let (kind, duration) = resolve_transition(t);
                    match kind {
                        TransitionKind::Dissolve | TransitionKind::Move => {
                            rs.background_transition = Some(BackgroundTransition {
                                old_background: rs.current_background.clone(),
                                new_background: path.clone(),
                                duration,
                            });
                            rs.set_background(path.clone());
                        }
                        TransitionKind::Fade => {
                            rs.scene_transition = Some(SceneTransition {
                                transition_type: SceneTransitionKind::Fade,
                                phase: SceneTransitionPhaseState::FadeIn,
                                duration,
                                pending_background: Some(path.clone()),
                            });
                        }
                        TransitionKind::FadeWhite => {
                            rs.scene_transition = Some(SceneTransition {
                                transition_type: SceneTransitionKind::FadeWhite,
                                phase: SceneTransitionPhaseState::FadeIn,
                                duration,
                                pending_background: Some(path.clone()),
                            });
                        }
                        TransitionKind::Rule {
                            mask_path,
                            reversed,
                            ramp,
                        } => {
                            rs.scene_transition = Some(SceneTransition {
                                transition_type: SceneTransitionKind::Rule {
                                    mask_path,
                                    reversed,
                                    ramp,
                                },
                                phase: SceneTransitionPhaseState::FadeIn,
                                duration,
                                pending_background: Some(path.clone()),
                            });
                        }
                        TransitionKind::None => rs.set_background(path.clone()),
                    }
                } else {
                    rs.set_background(path.clone());
                }
                ExecuteResult::Ok
            }
            _ => unreachable!("execute_background: unexpected command"),
        }
    }

    // ── 立绘 ─────────────────────────────────────────────────────────────────

    fn execute_character(
        &self,
        cmd: &Command,
        rs: &mut RenderState,
        manifest: &Manifest,
    ) -> ExecuteResult {
        match cmd {
            Command::ShowCharacter {
                path,
                alias,
                position,
                transition,
            } => {
                let (kind, duration) = transition
                    .as_ref()
                    .map_or((TransitionKind::None, 0.0), resolve_transition);

                let preset_name = crate::render_state::position_to_preset_name(*position);
                let preset = manifest.get_preset(preset_name);
                let group = manifest.get_group_config(path);

                if let Some(c) = rs.visible_characters.get_mut(alias) {
                    let is_position_change = c.position != *position;
                    let is_same_texture = c.texture_path == *path;

                    c.texture_path.clone_from(path);
                    c.position = *position;
                    c.target_alpha = 1.0;
                    c.pos_x = preset.x;
                    c.pos_y = preset.y;
                    c.anchor_x = group.anchor.x;
                    c.anchor_y = group.anchor.y;
                    c.render_scale = group.pre_scale * preset.scale;

                    if is_position_change && matches!(kind, TransitionKind::Move) {
                        c.transition_duration = Some(duration);
                    } else if is_same_texture && is_position_change {
                        c.transition_duration = None;
                        c.alpha = 1.0;
                    } else {
                        c.transition_duration = if matches!(kind, TransitionKind::None) {
                            c.alpha = 1.0;
                            None
                        } else {
                            Some(duration)
                        };
                    }
                } else {
                    let (start_alpha, trans_dur) = if matches!(kind, TransitionKind::None) {
                        (1.0, None)
                    } else {
                        (0.0, Some(duration))
                    };
                    rs.show_character(alias.clone(), path.clone(), *position, manifest);
                    if let Some(c) = rs.visible_characters.get_mut(alias) {
                        c.transition_duration = trans_dur;
                        c.alpha = start_alpha;
                        c.target_alpha = 1.0;
                    }
                }
                ExecuteResult::Ok
            }
            Command::HideCharacter { alias, transition } => {
                if let Some(t) = transition {
                    let (_, duration) = resolve_transition(t);
                    if let Some(c) = rs.visible_characters.get_mut(alias) {
                        c.transition_duration = Some(duration);
                        c.target_alpha = 0.0;
                        c.fading_out = true;
                    }
                } else {
                    rs.hide_character(alias);
                }
                ExecuteResult::Ok
            }
            Command::ClearCharacters => {
                rs.hide_all_characters();
                ExecuteResult::Ok
            }
            _ => unreachable!("execute_character: unexpected command"),
        }
    }

    // ── 文本框 ───────────────────────────────────────────────────────────────

    fn execute_text(&self, cmd: &Command, rs: &mut RenderState) -> ExecuteResult {
        match cmd {
            Command::ShowText {
                speaker,
                content,
                inline_effects,
                no_wait,
            } => {
                rs.start_typewriter(
                    speaker.clone(),
                    content.clone(),
                    inline_effects.clone(),
                    *no_wait,
                );
                if rs.text_mode == TextMode::NVL {
                    rs.nvl_entries.push(crate::render_state::NvlEntry {
                        speaker: speaker.clone(),
                        content: content.clone(),
                        visible_chars: 0,
                        is_complete: false,
                    });
                }
                ExecuteResult::WaitForClick
            }
            Command::ExtendText {
                content,
                inline_effects,
                no_wait,
            } => {
                rs.extend_dialogue(content, inline_effects.clone(), *no_wait);
                ExecuteResult::WaitForClick
            }
            Command::TextBoxHide => {
                rs.ui_visible = false;
                ExecuteResult::Ok
            }
            Command::TextBoxShow => {
                rs.ui_visible = true;
                ExecuteResult::Ok
            }
            Command::TextBoxClear => {
                rs.clear_dialogue();
                ExecuteResult::Ok
            }
            Command::SetTextMode(mode) => {
                if *mode == TextMode::ADV {
                    rs.nvl_entries.clear();
                }
                rs.text_mode = *mode;
                ExecuteResult::Ok
            }
            _ => unreachable!("execute_text: unexpected command"),
        }
    }

    // ── 选项 ─────────────────────────────────────────────────────────────────

    fn execute_choices(&self, cmd: &Command, rs: &mut RenderState) -> ExecuteResult {
        let Command::PresentChoices { choices, style } = cmd else {
            unreachable!("execute_choices: unexpected command");
        };
        rs.clear_dialogue();
        let items = choices
            .iter()
            .map(|c| ChoiceItem {
                text: c.text.clone(),
                target_label: c.target_label.clone(),
            })
            .collect();
        rs.set_choices(items, style.clone());
        ExecuteResult::WaitForChoice {
            choice_count: choices.len(),
        }
    }

    // ── 音频 ─────────────────────────────────────────────────────────────────

    fn execute_audio(&mut self, cmd: &Command) -> ExecuteResult {
        self.last_output.audio_command = Some(match cmd {
            Command::PlayBgm { path, looping } => AudioCommand::PlayBgm {
                path: path.clone(),
                looping: *looping,
                fade_in: None,
            },
            Command::StopBgm { fade_out } => AudioCommand::StopBgm {
                fade_out: fade_out.map(|f| f as f32),
            },
            Command::BgmDuck => AudioCommand::BgmDuck,
            Command::BgmUnduck => AudioCommand::BgmUnduck,
            Command::PlaySfx { path } => AudioCommand::PlaySfx { path: path.clone() },
            _ => unreachable!("execute_audio: unexpected command"),
        });
        ExecuteResult::Ok
    }

    // ── 演出效果 ─────────────────────────────────────────────────────────────

    fn execute_effects(&self, cmd: &Command, rs: &mut RenderState) -> ExecuteResult {
        match cmd {
            Command::ChapterMark { title, level } => {
                rs.set_chapter_mark(title.clone(), *level);
                ExecuteResult::Ok
            }
            Command::TitleCard { text, duration } => {
                rs.title_card = Some(crate::render_state::TitleCardState {
                    text: text.clone(),
                    duration: *duration as f32,
                    elapsed: 0.0,
                });
                ExecuteResult::Ok
            }
            _ => unreachable!("execute_effects: unexpected command"),
        }
    }

    fn execute_scene_effect(&mut self, cmd: &Command) -> ExecuteResult {
        let Command::SceneEffect { name, args } = cmd else {
            unreachable!("execute_scene_effect: unexpected command");
        };
        self.last_output.scene_effect_request = Some(SceneEffectRequest::from_command(name, args));
        ExecuteResult::Ok
    }

    // ── 流程控制 ─────────────────────────────────────────────────────────────

    fn execute_control(&self, cmd: &Command) -> ExecuteResult {
        match cmd {
            Command::Cutscene { path } => ExecuteResult::WaitForCutscene {
                video_path: path.clone(),
            },
            Command::FullRestart => ExecuteResult::FullRestart,
            Command::RequestUI { key, mode, params } => ExecuteResult::RequestUI {
                key: key.clone(),
                mode: mode.clone(),
                params: params.clone(),
            },
            _ => unreachable!("execute_control: unexpected command"),
        }
    }

    pub fn execute_batch(
        &mut self,
        cmds: &[Command],
        rs: &mut RenderState,
        manifest: &Manifest,
    ) -> BatchOutput {
        let mut final_result = ExecuteResult::Ok;
        let mut audio_commands = Vec::new();
        let mut scene_effect_request = None;
        for cmd in cmds {
            let result = self.execute(cmd, rs, manifest);
            if let Some(audio) = self.last_output.audio_command.take() {
                audio_commands.push(audio);
            }
            if let Some(effect) = self.last_output.scene_effect_request.take() {
                scene_effect_request = Some(effect);
            }
            if result != ExecuteResult::Ok {
                final_result = result;
            }
        }
        BatchOutput {
            result: final_result,
            audio_commands,
            scene_effect_request,
        }
    }
}

