1	use dioxus::prelude::*;
2	
3	use crate::render_state::RenderState;
4	
5	/// 资源 URL 构建
6	fn asset_url(path: &str) -> String {
7	    format!("http://ring-asset.localhost/{path}")
8	}
9	
10	/// 音频桥接组件：监听 `AudioRenderState` 变化，通过 JS Web Audio API 播放。
11	///
12	/// 不渲染任何 DOM。在 mount 时注入 JS `AudioManager`，
13	/// 每帧 diff BGM/SFX 状态并调用 JS 函数。
14	#[component]
15	pub fn AudioBridge(render_state: Signal<RenderState>) -> Element {
16	    // 注入 JS 音频管理器（仅首次 mount）
17	    use_effect(|| {
18	        document::eval(
19	            r#"
20	            window.__ringAudio = (function() {
21	                let bgmAudio = null;
22	                let bgmPath = null;
23	                let bgmFadeInterval = null;
24	
25	                function stopBgmFade() {
26	                    if (bgmFadeInterval) {
27	                        clearInterval(bgmFadeInterval);
28	                        bgmFadeInterval = null;
29	                    }
30	                }
31	
32	                function fadeBgmTo(targetVol, duration, onDone) {
33	                    stopBgmFade();
34	                    if (!bgmAudio || duration <= 0) {
35	                        if (bgmAudio) bgmAudio.volume = Math.max(0, Math.min(1, targetVol));
36	                        if (onDone) onDone();
37	                        return;
38	                    }
39	                    const startVol = bgmAudio.volume;
40	                    const steps = Math.max(1, Math.round(duration * 30));
41	                    const delta = (targetVol - startVol) / steps;
42	                    let step = 0;
43	                    bgmFadeInterval = setInterval(() => {
44	                        step++;
45	                        if (step >= steps) {
46	                            bgmAudio.volume = Math.max(0, Math.min(1, targetVol));
47	                            stopBgmFade();
48	                            if (onDone) onDone();
49	                        } else {
50	                            bgmAudio.volume = Math.max(0, Math.min(1, startVol + delta * step));
51	                        }
52	                    }, (duration * 1000) / steps);
53	                }
54	
55	                return {
56	                    playBgm(url, loop_, volume, fadeDuration) {
57	                        if (bgmPath === url) {
58	                            // same track, just update volume
59	                            if (bgmAudio) {
60	                                const v = Math.max(0, Math.min(1, volume));
61	                                if (fadeDuration > 0) {
62	                                    fadeBgmTo(v, fadeDuration);
63	                                } else {
64	                                    stopBgmFade();
65	                                    bgmAudio.volume = v;
66	                                }
67	                            }
68	                            return;
69	                        }
70	                        // different track: crossfade
71	                        const oldAudio = bgmAudio;
72	                        const newAudio = new Audio(url);
73	                        newAudio.loop = loop_;
74	                        newAudio.volume = 0;
75	                        bgmAudio = newAudio;
